'use strict';
const MusicSections=(()=>{
 let selected=null,owner=null,busy=false;const drafts=new Map();
 const sections=()=>S.p?.music_sections?.sections||[];
 const picked=()=>owner===S.p?.id?sections().find(s=>s.id===selected):null;
 const matches=s=>s.recognition?.tracks?.length?s.recognition.tracks:(S.p?.music?.tracks||[]).filter(t=>!t.deleted&&(t.positions||[t.time]).some(p=>p>=s.start&&p<s.end));
 const title=s=>matches(s)[0]?.title||`配乐 ${String(sections().indexOf(s)+1).padStart(2,'0')}`;
 const action=(label,key,glyph,attrs='')=>`<button class="button" data-music-section-action="${key}" ${attrs}>${icon(glyph)}${label}</button>`;
 function choose(id,play=false,fromTimeline=false){const s=sections().find(s=>s.id===id);if(!s)return;if(!play)Clips.clearAudition();selected=id;owner=S.p.id;if(fromTimeline){seek(s.start);if(!S.collectionOpen||S.collection!=='music'){paint();return;}}S.collection='music';S.collectionOpen=true;Studio.syncPanels();renderCollection();if(fromTimeline)CollectionLink.reveal('music',id);else $('#collection-list').scrollTop=0;if(play){Clips.startAudition(s.start,s.end);seek(s.start);if(ClipMixer.existing().includes('background')&&ClipMixer.state().solo!=='background')ClipMixer.control('background','solo');Clips.beforePlay();$('#video')?.play().catch(e=>{if(e.name!=='AbortError')toast(e.message)});}paint();}
 function paint(){const active=picked();$$('[data-music-section]').forEach(b=>{b.classList.toggle('active',b.dataset.musicSection===active?.id);b.setAttribute('aria-pressed',String(b.dataset.musicSection===active?.id));if(b.classList.contains('music-section-label')){const span=b.querySelector('span'),scroll=$('.clip-track-scroll');if(span&&scroll){const shift=Math.max(0,Math.min(scroll.scrollLeft-b.offsetLeft,b.clientWidth-span.offsetWidth-20));span.style.transform=`translateX(${shift}px)`;}}});}
 function labels(){return sections().map(s=>`<button class="music-section-label ${picked()?.id===s.id?'active':''}" data-music-section="${esc(s.id)}" style="left:${s.start/S.p.duration*100}%;width:calc(${(s.end-s.start)/S.p.duration*100}% - 4px)" title="${esc(title(s))} · ${clock(s.start)}—${clock(s.end)} · 点击查看、试听或识曲" aria-label="音乐段 ${clock(s.start)}—${clock(s.end)} · ${esc(title(s))}" aria-pressed="${picked()?.id===s.id}"><span>${esc(title(s))}</span></button>`).join('');}
 function panel(){const state=S.p.music_sections;if(!S.p.has_audio)return '';const list=sections();if(owner!==S.p.id){owner=S.p.id;selected=null;}const current=picked(),pending=['processing','waiting_audio'].includes(state?.status);
 const header=`<div class="music-sections-head"><strong>音乐分段</strong>${action('切开','split','scissors','title="在播放头切开背景声" aria-label="在播放头切开音乐"')}<button class="icon-btn" data-music-section-action="undo" title="撤销上次分段调整" aria-label="撤销上次分段调整" ${!state?.history?.length?'disabled':''}>${icon('back')}</button></div>`;
 const status=state?.status==='error'?`<p class="section-status" role="status">${esc(state.message)} ${action('重试','retry','refresh')}</p>`:pending?`<p class="section-status" role="status">${esc(state.message||'正在查找音乐变化位置…')}</p>`:`<p class="section-status">${list.some(s=>s.origin==='suggested')?'切点是换音乐的建议位置，可逐段试听、调整。':'点击一段，试听或查找对应歌曲。'}</p>`;
 const rows=list.map(s=>`<button class="music-section-row ${s.id===current?.id?'active':''}" data-music-section="${esc(s.id)}"><span class="section-symbol">${icon('music')}</span><span><strong>${esc(title(s))}</strong><small>${clock(s.start)}—${clock(s.end)}${s.origin==='suggested'?' · 建议分段':''}</small></span>${icon('chevron')}</button>`).join('');
 let detail='';if(current){const r=current.recognition||{},working=['queued','processing'].includes(r.status),index=list.indexOf(current),found=matches(current);detail=`<div class="music-section-detail"><div class="row"><strong>${esc(title(current))}</strong><span class="spacer"></span><button class="icon-btn" data-music-section-action="close" aria-label="收起音乐段详情">${icon('close')}</button></div><p>${clock(current.start)}—${clock(current.end)} · ${(current.end-current.start).toFixed(2)} 秒</p><div class="section-actions">${action('试听本段','play','play','title="只听这一段背景声，到结尾停止，不接着播放下一段"')}${action(working?'识别中…':'识别本段歌曲','recognize','search',working?'disabled':'')}</div>${working?`<p role="status">${esc(r.message)}</p>`:r.status==='error'?`<p role="alert">${esc(r.message)}</p>`:r.status==='ready'&&!r.tracks.length?`<p>${esc(r.message)}</p>`:''}${found.map(t=>`<div class="section-song">${safeLink(t.artwork_url)?`<img src="${esc(safeLink(t.artwork_url))}" alt="" loading="lazy" referrerpolicy="no-referrer">`:icon('music')}<div><strong>${esc(t.title)}</strong><small>${esc(t.artist)}</small>${!r.tracks?.length?'<small>此前在本段内识别到</small>':''}</div>${safeLink(t.song_url)?`<a class="icon-btn" href="${esc(safeLink(t.song_url))}" target="_blank" rel="noopener noreferrer" aria-label="查看 ${esc(t.title)} 歌曲资料">${icon('arrow')}</a>`:''}</div>`).join('')}${index>0?`<div class="section-boundary"><label>与上一段的分界（秒）<input id="music-boundary" type="number" step="0.1" min="${list[index-1].start+.1}" max="${current.end-.1}" value="${esc(drafts.get(owner+':'+current.id)??Number(current.start.toFixed(3)))}"></label>${action('调整切点','boundary','check')}${action('与上一段合并','merge','copy')}</div>`:''}<small class="section-note">识曲需联网。这里只切分时间，不分离音乐和音效。</small></div>`;}
 return `<section class="music-sections">${header}${status}${detail}<div class="music-section-list">${rows}</div></section><h3 class="recognized-songs-heading">整片识曲记录</h3>`;
 }
 async function request(action,extra={}){if(busy)return;busy=true;const pid=S.p.id,current=picked(),currentIndex=sections().indexOf(current),revision=S.p.music_sections?.revision??0;try{const p=await api(url(pid,'/music_sections'),{action,id:current?.id,expected_revision:revision,...extra});upsert(p);if(S.p?.id===pid){if(action==='split'||action==='boundary'||action==='merge'||action==='undo'){const list=p.music_sections.sections;selected=(action==='boundary'?list[currentIndex]:action==='merge'?list[currentIndex-1]:list.find(s=>S.position>=s.start&&S.position<s.end))?.id||list[0]?.id;}renderTracks();renderCollection();}return p;}catch(error){toast(error.message);}finally{busy=false;}}
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-music-section],[data-music-section-action]');if(!b||b.disabled)return;if(b.dataset.musicSection){choose(b.dataset.musicSection,false,b.classList.contains('music-section-label'));return;}const key=b.dataset.musicSectionAction;try{if(key==='close'){Clips.clearAudition();selected=null;renderCollection();paint();return;}if(key==='play'){if(picked())choose(picked().id,true);return;}if(['split','merge','boundary','undo'].includes(key)&&ClipMixer.state().tracks.background.locked)throw new Error('背景声轨已锁定，请先解锁再调整分段。');if(key==='retry'){await startStudy(S.p.id);return;}if(key==='split'){S.collection='music';S.collectionOpen=true;Studio.syncPanels();await request('split',{time:S.position});}else if(key==='boundary'){const value=Number($('#music-boundary').value);await request('boundary',{time:value});}else await request(key);}catch(error){toast(error.message)}});
 document.addEventListener('input',e=>{if(e.target.id==='music-boundary'&&picked())drafts.set(owner+':'+picked().id,e.target.value);});
 return {sections,title,labels,panel,paint};
})();
